bool Consultation::programmer_consultation(const std::string& id_patient,
                                           const std::string& id_professionnel,
                                           const std::string& motif,
                                           const std::string& date_debut,
                                           const std::string& date_fin)
{
    Database db;

    // Vérifier que le patient existe et récupérer son dossier
    int id_dossier = db.get_id_dossier_medical(id_patient);
    if (id_dossier == 0) {
        std::cout << "Erreur : dossier medical introuvable pour ce patient.\n";
        return false;
    }

    // Vérifier que le professionnel existe
    if (!db.professionnel_existe(id_professionnel)) {
        std::cout << "Erreur : professionnel introuvable.\n";
        return false;
    }

    // Vérification format dates et ordre
    if (!db.estFormatDateHeureValide(date_debut) ||
        !db.estFormatDateHeureValide(date_fin)) {
        std::cout << "Format de date invalide ! Utilisez YYYY-MM-DD HH:MM\n";
        return false;
    }

    if (!db.dateFinApresDebut(date_debut, date_fin)) {
        std::cout << "Erreur : la date de fin doit etre apres la date de debut.\n";
        return false;
    }

    // Vérifier conflit consultation
    if (db.verifier_conflit_consultation(id_professionnel, date_debut, date_fin)) {
        std::cout << "Conflit : le professionnel a deje une consultation dans cette plage horaire.\n";
        return false;
    }

    // Enregistrement en BD
    string motif_sql = motif;
    size_t pos = 0;
    while ((pos = motif_sql.find('\'', pos)) != string::npos)
    {
        motif_sql.replace(pos, 1, "''");
        pos += 2;
    }
    ostringstream oss;
    oss << "INSERT INTO Consultation "
        << "(id_dossier_medical, id_professionnel, date_debut, date_fin, motif, statut) "
        << "VALUES ("
        << id_dossier << ", '"
        << id_professionnel << "', '"
        << date_debut << "', '"
        << date_fin << "', '"
        << motif_sql << "', 0);";

    if (!db.executer(oss.str())) {
        std::cout << "Erreur SQL : impossible d'enregistrer la consultation.\n";
        return false;
    }

    std::cout << "Consultation programmee avec succes.\n";
    return true;
}

