bool Database::verifier_format_date_heure(const std::string& date)
{
    // Format attendu : YYYY-MM-DD HH:MM
    std::regex pattern(R"(^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$)");
    return std::regex_match(date, pattern);
}

bool Database::date_fin_apres_debut(const std::string& debut, const std::string& fin)
{
    std::tm tm_debut = {}, tm_fin = {};
    std::istringstream ss1(debut);
    std::istringstream ss2(fin);
    ss1 >> std::get_time(&tm_debut, "%Y-%m-%d %H:%M");
    ss2 >> std::get_time(&tm_fin, "%Y-%m-%d %H:%M");
    if (ss1.fail() || ss2.fail()) return false;
    return std::mktime(&tm_fin) > std::mktime(&tm_debut);
}


// -------------------- Constructeur / Destructeur --------------------
Database::Database() {
    if (sqlite3_open("MediPass_DB.db", &db) != SQLITE_OK) {
        cerr << "Erreur ouverture BD: " << (db ? sqlite3_errmsg(db) : "BD non initialisee") << endl;
        db = nullptr;
    }
}

Database::~Database() {
    if (db) sqlite3_close(db);
}

// -------------------- Exécution SQL interne --------------------
int Database::exec_sql_internal(const string& sql, int (*callback)(void*,int,char**,char**), void* data) {
    if (!db) {
        cerr << "Erreur: Base de donnees non ouverte.\n";
        return SQLITE_ERROR;
    }
    char* errMsg = nullptr;
    int rc = sqlite3_exec(db, sql.c_str(), callback, data, &errMsg);
    if (rc != SQLITE_OK) {
        cerr << "Erreur SQL: " << (errMsg ? errMsg : "inconnue") << "\nRequete: " << sql << endl;
        if (errMsg) sqlite3_free(errMsg);
    }
    return rc;
}

int Database::callback_afficher(void* NotUsed, int argc, char** argv, char** azColName) {
    for (int i = 0; i < argc; i++) {
        cout << azColName[i] << ": " << (argv[i] ? argv[i] : "NULL") << " | ";
    }
    cout << endl;
    return 0;
}

void Database::afficherS(const string& sql) {
    exec_sql_internal(sql, callback_afficher, nullptr);
}


// -------------------- Initialisation BD --------------------
void Database::initialiser(bool reset) {
    if (!db) return;


    exec_sql_internal("PRAGMA foreign_keys = OFF;");
    exec_sql_internal("BEGIN IMMEDIATE;");

    if (reset) {
        const char* drop_sql = R"(
            PRAGMA writable_schema = 1;
            DELETE FROM sqlite_master WHERE type IN ('table','index','trigger');
            PRAGMA writable_schema = 0;
            COMMIT;

            VACUUM;
        )";
        exec_sql_internal(drop_sql);
    }

    const char* create_sql = R"(
        CREATE TABLE IF NOT EXISTS Utilisateur (
            id TEXT PRIMARY KEY,
            nom TEXT NOT NULL,
            prenom TEXT NOT NULL,
            telephone TEXT,
            sexe TEXT,
            login TEXT UNIQUE NOT NULL,
            password TEXT NOT NULL,
            est_administrateur INTEGER DEFAULT 0
        );

        CREATE TABLE IF NOT EXISTS Administrateur (
            id_admin TEXT PRIMARY KEY,
            id_utilisateur TEXT UNIQUE NOT NULL,
            FOREIGN KEY(id_utilisateur) REFERENCES Utilisateur(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS ProfessionnelDeSante (
            id_professionnel TEXT PRIMARY KEY,
            id_utilisateur TEXT UNIQUE NOT NULL,
            specialite TEXT DEFAULT 'a_definir',
            autorisation INTEGER DEFAULT 1,
            premiere_connexion INTEGER DEFAULT 1,
            FOREIGN KEY(id_utilisateur) REFERENCES Utilisateur(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS Patient (
            id_patient TEXT PRIMARY KEY,
            nom TEXT NOT NULL,
            prenom TEXT NOT NULL,
            date_naissance TEXT,
            sexe TEXT,
            telephone TEXT
        );

        CREATE TABLE IF NOT EXISTS DossierMedical (
            id_dossier_medical INTEGER PRIMARY KEY AUTOINCREMENT,
            id_patient TEXT NOT NULL,
            poids REAL,
            taille REAL,
            FOREIGN KEY(id_patient) REFERENCES Patient(id_patient) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS Consultation (
            id_consultation INTEGER PRIMARY KEY AUTOINCREMENT,
            id_dossier_medical INTEGER NOT NULL,
            id_professionnel TEXT NOT NULL,
            date_debut TEXT,
            date_fin TEXT,
            motif TEXT,
            diagnostic TEXT,
            statut INTEGER DEFAULT 0,
            FOREIGN KEY(id_dossier_medical) REFERENCES DossierMedical(id_dossier_medical) ON DELETE CASCADE,
            FOREIGN KEY(id_professionnel) REFERENCES ProfessionnelDeSante(id_professionnel)
        );

        CREATE TABLE IF NOT EXISTS habilitations (
            id_professionnel TEXT NOT NULL,
            id_beneficiaire TEXT NOT NULL,
            id_patient TEXT NOT NULL,
            motif TEXT DEFAULT 'acces autorise',
            PRIMARY KEY (id_professionnel, id_beneficiaire, id_patient),
            FOREIGN KEY(id_professionnel) REFERENCES ProfessionnelDeSante(id_professionnel) ON DELETE CASCADE,
            FOREIGN KEY(id_beneficiaire) REFERENCES Utilisateur(id) ON DELETE CASCADE,
            FOREIGN KEY(id_patient) REFERENCES Patient(id_patient) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS Examen (
            id_examen INTEGER PRIMARY KEY AUTOINCREMENT,
            id_dossier_medical INTEGER NOT NULL,
            type_examen TEXT NOT NULL,
            date_examen TEXT,
            resultat TEXT,
            prescription TEXT,
            FOREIGN KEY(id_dossier_medical) REFERENCES DossierMedical(id_dossier_medical) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS Antecedent (
            id_antecedent INTEGER PRIMARY KEY AUTOINCREMENT,
            id_dossier_medical TEXT NOT NULL,
            type_antecedent TEXT NOT NULL,
            description TEXT NOT NULL,
            date_enregistrement TEXT NOT NULL,
            FOREIGN KEY(id_dossier_medical) REFERENCES DossierMedical(id_dossier_medical) ON DELETE CASCADE
        );

    )";

    exec_sql_internal(create_sql);
    exec_sql_internal("PRAGMA foreign_keys = ON;");
    exec_sql_internal("COMMIT;");

    //cout << "Initialisation terminee (reset=" << (reset ? "true" : "false") << ")." << endl;
}

