string Database::generer_id_professionnel() {
    int max_num = 0;
    const char* sql = "SELECT MAX(CAST(SUBSTR(id_professionnel,3) AS INTEGER)) FROM ProfessionnelDeSante WHERE id_professionnel LIKE 'PR%';";
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW) max_num = sqlite3_column_int(stmt, 0);
        sqlite3_finalize(stmt);
    }
    ostringstream oss; oss << "PR" << setw(3) << setfill('0') << max_num + 1;
    return oss.str();
}

