// -------------------- Gestion administrateur --------------------
string Database::get_admin_utilisateur_id() {
    string admin_id;
    const char* sql = "SELECT id FROM Utilisateur WHERE est_administrateur=1 LIMIT 1;";
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW)
            admin_id = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
        sqlite3_finalize(stmt);
    }
    if (!admin_id.empty()) return admin_id;

    string new_id = generer_id_utilisateur();
    string default_hash = Authentification::hasher_mot_de_passe("admin123");
    const char* insert_sql = "INSERT INTO Utilisateur(id,nom,prenom,telephone,sexe,login,password,est_administrateur) VALUES(?, 'Admin', 'System', '', '', 'admin', ?, 1);";
    sqlite3_stmt* stmt2;
    if (sqlite3_prepare_v2(db, insert_sql, -1, &stmt2, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt2, 1, new_id.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt2, 2, default_hash.c_str(), -1, SQLITE_STATIC);
        if (sqlite3_step(stmt2) == SQLITE_DONE) admin_id = new_id;
        sqlite3_finalize(stmt2);
    }

    return admin_id;
}




