bool Database::creer_professionnel(const std::string& id,
                                   const std::string& nom,
                                   const std::string& prenom,
                                   const std::string& tel,
                                   const std::string& sexe,
                                   const std::string& login,
                                   const std::string& hash,
                                   const std::string& specialite,
                                   bool premiere_connexion,
                                   bool autorisation)
{
    if (!db) {
        std::cerr << "Base de donnees non initialisee.\n";
        return false;
    }

    char* errmsg = nullptr;
    int rc;

    // 1) Insertion dans Utilisateur
    std::stringstream ss_util;
    ss_util << "INSERT INTO Utilisateur (id, nom, prenom, telephone, sexe, login, password, est_administrateur) VALUES ("
            << "'" << id << "', "
            << "'" << nom << "', "
            << "'" << prenom << "', "
            << "'" << tel << "', "
            << "'" << sexe << "', "
            << "'" << login << "', "
            << "'" << hash << "', "
            << "0);"; // ce n'est pas un admin
    rc = sqlite3_exec(db, ss_util.str().c_str(), nullptr, nullptr, &errmsg);
    if (rc != SQLITE_OK) {
        std::cerr << "Erreur lors de l'insertion dans Utilisateur : " << errmsg << "\n";
        sqlite3_free(errmsg);
        return false;
    }

    // 2) Insertion dans ProfessionnelDeSante
    std::stringstream ss_prof;
    ss_prof << "INSERT INTO ProfessionnelDeSante (id_professionnel, id_utilisateur, specialite, premiere_connexion, autorisation) VALUES ("
            << "'" << id << "', "
            << "'" << id << "', "
            << "'" << specialite << "', "
            << (premiere_connexion ? 1 : 0) << ", "
            << (autorisation ? 1 : 0) << ");";

    rc = sqlite3_exec(db, ss_prof.str().c_str(), nullptr, nullptr, &errmsg);
    if (rc != SQLITE_OK) {
        std::cerr << "Erreur lors de l'insertion dans ProfessionnelDeSante : " << errmsg << "\n";
        sqlite3_free(errmsg);
        return false;
    }

    return true;
}


