bool Database::est_autorise(const std::string& id_beneficiaire,
                            const std::string& id_patient,
                            const std::string& action)
{
    sqlite3_stmt* stmt;
    const char* sql;

    // 1. Vérifier habilitation explicite
    sql = "SELECT COUNT(*) FROM habilitations "
          "WHERE id_beneficiaire = ? AND id_patient = ?;";
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        return false;
    }

    sqlite3_bind_text(stmt, 1, id_beneficiaire.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 2, id_patient.c_str(), -1, SQLITE_TRANSIENT);

    int habilite = 0;
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        habilite = sqlite3_column_int(stmt, 0);
    }
    sqlite3_finalize(stmt);

    if (habilite > 0)
        return true;

    // 2. Vérifier consultation directe
    sql = "SELECT COUNT(*) "
          "FROM Consultation c "
          "JOIN DossierMedical d ON c.id_dossier_medical = d.id_dossier_medical "
          "WHERE c.id_professionnel = ? AND d.id_patient = ?;";
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        return false;
    }

    sqlite3_bind_text(stmt, 1, id_beneficiaire.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 2, id_patient.c_str(), -1, SQLITE_TRANSIENT);

    int consultation = 0;
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        consultation = sqlite3_column_int(stmt, 0);
    }
    sqlite3_finalize(stmt);

    return consultation > 0;
}



