bool Database::ajouter_habilitation(const std::string& id_professionnel,
                                    const std::string& id_beneficiaire,
                                    const std::string& id_patient,
                                    const std::string& motif)
{
    if (!db) return false;

    // Vérifier que grantor a une consultation avec le patient
    if (!professionnel_a_consultation(id_professionnel, id_patient)) {
        // seul un pro ayant une consultation peut habiliter
        return false;
    }

    // Insérer (ou remplacer) dans la table habilitations
    sqlite3_stmt* stmt = nullptr;
    const std::string sql =
        "INSERT OR REPLACE INTO habilitations (id_professionnel, id_beneficiaire, id_patient, motif) "
        "VALUES (?, ?, ?, ?);";

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
        sqlite3_finalize(stmt);
        return false;
    }

    sqlite3_bind_text(stmt, 1, id_professionnel.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 2, id_beneficiaire.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 3, id_patient.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 4, motif.c_str(), -1, SQLITE_TRANSIENT);

    int rc = sqlite3_step(stmt);
    sqlite3_finalize(stmt);
    return (rc == SQLITE_DONE);
}






bool Database::ajouter_consultation(const std::string& id_patient,
                                    const std::string& id_professionnel,
                                    const std::string& motif,
                                    const std::string& date_debut,
                                    const std::string& date_fin)
{
    // Récupérer l'id du dossier médical
    Database db;
    int id_dossier = db.get_id_dossier_medical(id_patient);
    if (id_dossier == 0) {
        cerr << "Dossier medical introuvable pour le patient " << id_patient << std::endl;
        return false;
    }

    // Vérifier que le professionnel a le droit de programmer la consultation
    if (!db.verifier_habilitation(id_professionnel, "programmer", id_patient)) {
        cerr << "Acces refuse : le professionnel n'est pas habilite.\n";
        return false;
    }

    // Vérifier le format des dates et la cohérence
    if (!Database::verifier_format_date_heure(date_debut) ||
        !Database::verifier_format_date_heure(date_fin) ||
        !Database::date_fin_apres_debut(date_debut, date_fin))
    {
        cerr << "Dates invalides.\n";
        return false;
    }

    // Insertion dans la table Consultation
    std::ostringstream oss;
    oss << "INSERT INTO Consultation(id_dossier_medical, id_professionnel, motif, date_debut, date_fin) VALUES('"
        << id_dossier << "','" << id_professionnel << "','" << motif << "','" << date_debut << "','" << date_fin << "');";

    char* errMsg = nullptr;
    int rc = sqlite3_exec(db.db, oss.str().c_str(), nullptr, nullptr, &errMsg);
    if (rc != SQLITE_OK) {
        std::cerr << "Erreur ajout consultation: " << errMsg << std::endl;
        sqlite3_free(errMsg);
        return false;
    }

    std::cout << "Consultation programmee avec succes.\n";
    return true;
}

