            return 0;
        }
    }

    std::string sql = "SELECT id_dossier_medical FROM DossierMedical WHERE id_patient = ?;";
    sqlite3_stmt* stmt;

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
        std::cerr << "Erreur préparation requête SQLite.\n";
        return 0;
    }

    sqlite3_bind_text(stmt, 1, id_patient.c_str(), -1, SQLITE_STATIC);

    if (sqlite3_step(stmt) == SQLITE_ROW) {
        id_dossier = sqlite3_column_int(stmt, 0);
    }

    sqlite3_finalize(stmt);

    return id_dossier; // retourne 0 si non trouvé
}



// 1. Récupérer l'ID patient
std::string Database::get_id_patient(const std::string& nom, const std::string& prenom) {
    sqlite3* db;
    std::string id_patient;

    if (sqlite3_open("MediPass_DB.db", &db) == SQLITE_OK) {
        const char* sql = "SELECT id_patient FROM Patient WHERE nom = ? AND prenom = ?;";
        sqlite3_stmt* stmt;

        if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) == SQLITE_OK) {
            sqlite3_bind_text(stmt, 1, nom.c_str(), -1, SQLITE_STATIC);
            sqlite3_bind_text(stmt, 2, prenom.c_str(), -1, SQLITE_STATIC);

            if (sqlite3_step(stmt) == SQLITE_ROW) {
                const unsigned char* text = sqlite3_column_text(stmt, 0);
                if (text) id_patient = reinterpret_cast<const char*>(text);
            }
            sqlite3_finalize(stmt);
        }
        sqlite3_close(db);
    }
    return id_patient; // vide si introuvable
}


// 2. Vérifier habilitation
bool Database::verifier_habilitation(const std::string& id_professionnel,
                                     const std::string& id_beneficiaire,
                                     const std::string& id_patient)
{
    if (!db) return false; // Vérification que la base est ouverte

    std::string sql = "SELECT COUNT(*) FROM habilitations "
                      "WHERE id_professionnel = ? "
                      "AND id_beneficiaire = ? "
                      "AND id_patient = ?;";

    sqlite3_stmt* stmt = nullptr;
    bool ok = false;

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, id_professionnel.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 2, id_beneficiaire.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 3, id_patient.c_str(), -1, SQLITE_STATIC);

        if (sqlite3_step(stmt) == SQLITE_ROW) {
            ok = sqlite3_column_int(stmt, 0) > 0; // Si count > 0, habilitation ok
        }
    } else {
        std::cerr << "Erreur préparation SQL verifier_habilitation: "
                  << sqlite3_errmsg(db) << std::endl;
    }

    sqlite3_finalize(stmt);
    return ok;
}

// 3. Créer ou récupérer dossier médical
int Database::create_or_get_dossier_medical(const std::string& id_patient, double poids, double taille) {
    int id_dossier = get_id_dossier_medical(id_patient);
    if (id_dossier != 0) return id_dossier;

    std::string sql = "INSERT INTO DossierMedical (id_patient, poids, taille) VALUES (?, ?, ?);";
    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, id_patient.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_double(stmt, 2, poids);
        sqlite3_bind_double(stmt, 3, taille);
        sqlite3_step(stmt);
    }
    sqlite3_finalize(stmt);
    return get_id_dossier_medical(id_patient);
}




bool Database::verifier_conflit_consultation(const std::string& id_professionnel, const std::string& date_debut, const std::string& date_fin) {
    std::string sql = "SELECT COUNT(*) FROM Consultation WHERE id_professionnel=? AND ((? BETWEEN date_debut AND date_fin) OR (? BETWEEN date_debut AND date_fin));";
    sqlite3_stmt* stmt;
    bool conflict = false;
    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, id_professionnel.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 2, date_debut.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 3, date_fin.c_str(), -1, SQLITE_STATIC);
        if (sqlite3_step(stmt) == SQLITE_ROW) {
            conflict = sqlite3_column_int(stmt, 0) > 0;
        }
    }
    sqlite3_finalize(stmt);
    return conflict;
}


