bool Database::creer_administrateur(const std::string& id,
                                    const std::string& nom,
                                    const std::string& prenom,
                                    const std::string& tel,
                                    const std::string& sexe,
                                    const std::string& login,
                                    const std::string& hash)
{
    if (!db) {
        std::cerr << "Base de donnees non initialisee.\n";
        return false;
    }

    char* errmsg = nullptr;
    int rc;

    // 1) Insertion dans Utilisateur (avec est_administrateur = 1)
    std::stringstream ss_util;
    ss_util << "INSERT INTO Utilisateur (id, nom, prenom, telephone, sexe, login, password, est_administrateur) VALUES ("
            << "'" << id << "', "
            << "'" << nom << "', "
            << "'" << prenom << "', "
            << "'" << tel << "', "
            << "'" << sexe << "', "
            << "'" << login << "', "
            << "'" << hash << "', "
            << "1);"; // administrateur
    rc = sqlite3_exec(db, ss_util.str().c_str(), nullptr, nullptr, &errmsg);
    if (rc != SQLITE_OK) {
        //cerr << "Erreur lors de l'insertion dans Utilisateur : " << errmsg << "\n";
        sqlite3_free(errmsg);
        return false;
    }

    // 2) Insertion dans Administrateur
    std::stringstream ss_admin;
    ss_admin << "INSERT INTO Administrateur (id_admin, id_utilisateur) VALUES ("
             << "'" << id << "', "
             << "'" << id << "');";

    rc = sqlite3_exec(db, ss_admin.str().c_str(), nullptr, nullptr, &errmsg);
    if (rc != SQLITE_OK) {
        std::cerr << "Erreur lors de l'insertion dans Administrateur : " << errmsg << "\n";
        sqlite3_free(errmsg);
        return false;
    }

    return true;
}


