bool Database::estFormatDateValide(const std::string& date) {
    if (date.size() != 10) return false;

    if (date[4] != '-' || date[7] != '-') return false;

    int annee, mois, jour;
    try {
        annee = std::stoi(date.substr(0, 4));
        mois  = std::stoi(date.substr(5, 2));
        jour  = std::stoi(date.substr(8, 2));
    } catch (...) {
        return false;
    }

    if (mois < 1 || mois > 12) return false;
    if (jour < 1 || jour > 31) return false;

    return true;
}



bool Database::estHeureValide(const std::string& heure) {
    if (heure.size() != 5) return false;

    if (heure[2] != ':') return false;

    int h, m;
    try {
        h = std::stoi(heure.substr(0, 2));
        m = std::stoi(heure.substr(3, 2));
    } catch (...) {
        return false;
    }

    if (h < 0 || h > 23) return false;
    if (m < 0 || m > 59) return false;

    return true;
}


bool Database::dateFinApresDebut(const std::string& date_debut,
                                 const std::string& heure_debut,
                                 const std::string& date_fin,
                                 const std::string& heure_fin)
{
    // Vérifier formats valides
    if (!estFormatDateValide(date_debut) ||
        !estFormatDateValide(date_fin) ||
        !estHeureValide(heure_debut) ||
        !estHeureValide(heure_fin))
        return false;

    // Extraction des valeurs
    int an1 = stoi(date_debut.substr(0, 4));
    int mo1 = stoi(date_debut.substr(5, 2));
    int jo1 = stoi(date_debut.substr(8, 2));
    int h1  = stoi(heure_debut.substr(0, 2));
    int m1  = stoi(heure_debut.substr(3, 2));

    int an2 = stoi(date_fin.substr(0, 4));
    int mo2 = stoi(date_fin.substr(5, 2));
    int jo2 = stoi(date_fin.substr(8, 2));
    int h2  = stoi(heure_fin.substr(0, 2));
    int m2  = stoi(heure_fin.substr(3, 2));

    // Comparaison date
    if (an2 > an1) return true;
    if (an2 < an1) return false;

    if (mo2 > mo1) return true;
    if (mo2 < mo1) return false;

    if (jo2 > jo1) return true;
    if (jo2 < jo1) return false;

    // Si même jour → comparer l'heure
    if (h2 > h1) return true;
    if (h2 < h1) return false;

    return (m2 > m1);
}

bool Database::estFormatDateHeureValide(const std::string& datetime) {
    if (datetime.size() != 16) return false; // 10 + 1 + 5
    if (datetime[4] != '-' || datetime[7] != '-' || datetime[10] != ' ' || datetime[13] != ':')
        return false;

    try {
        int annee = std::stoi(datetime.substr(0,4));
        int mois  = std::stoi(datetime.substr(5,2));
        int jour  = std::stoi(datetime.substr(8,2));
        int heure = std::stoi(datetime.substr(11,2));
        int min   = std::stoi(datetime.substr(14,2));

        if (mois < 1 || mois > 12) return false;
        if (jour < 1 || jour > 31) return false;
        if (heure < 0 || heure > 23) return false;
        if (min < 0 || min > 59) return false;

        return true;
    } catch (...) {
        return false;
    }
}

bool Database::dateFinApresDebut(const std::string& datetime_debut,
                                 const std::string& datetime_fin)
{
    if (!estFormatDateHeureValide(datetime_debut) ||
        !estFormatDateHeureValide(datetime_fin))
        return false;

    struct tm tm_debut = {}, tm_fin = {};
    std::istringstream ss_debut(datetime_debut);
    std::istringstream ss_fin(datetime_fin);

    ss_debut >> std::get_time(&tm_debut, "%Y-%m-%d %H:%M");
    ss_fin >> std::get_time(&tm_fin, "%Y-%m-%d %H:%M");

    if (ss_debut.fail() || ss_fin.fail()) return false;

    time_t t_debut = mktime(&tm_debut);
    time_t t_fin   = mktime(&tm_fin);

    return difftime(t_fin, t_debut) > 0;
}



