    std::string sql = "SELECT password FROM Utilisateur WHERE login='" + login + "';"; // ou mot_de_passe si tu changes la colonne
    sqlite3_stmt* stmt;
    std::string hash = "";

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW) {
            const unsigned char* text = sqlite3_column_text(stmt, 0);
            if (text) hash = std::string(reinterpret_cast<const char*>(text));
        }
        sqlite3_finalize(stmt);
    } else {
        std::cerr << "Erreur SQL (get_mot_de_passe): " << sqlite3_errmsg(db) << std::endl;
    }

    return hash;
}


