int Database::executerCount(const string& sql, const std::vector<string>& params)
{
    if (!db) return 0;
    sqlite3_stmt* stmt = nullptr;
    int result = 0;

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
        sqlite3_finalize(stmt);
        return 0;
    }

    // bind params (1-based)
    for (size_t i = 0; i < params.size(); ++i) {
        sqlite3_bind_text(stmt, int(i+1), params[i].c_str(), -1, SQLITE_TRANSIENT);
    }

    if (sqlite3_step(stmt) == SQLITE_ROW) {
        result = sqlite3_column_int(stmt, 0);
    }

    sqlite3_finalize(stmt);
    return result;
}


bool Database::professionnel_a_consultation(const std::string& id_prof, const std::string& id_patient) {
    sqlite3_stmt* stmt;
    const char* sql =
        "SELECT COUNT(*) FROM Consultation c "
        "JOIN DossierMedical d ON c.id_dossier_medical = d.id_dossier_medical "
        "WHERE c.id_professionnel = ? AND d.id_patient = ?;";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) != SQLITE_OK) {
        return false;
    }

    sqlite3_bind_text(stmt, 1, id_prof.c_str(), -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 2, id_patient.c_str(), -1, SQLITE_TRANSIENT);

    bool result = false;
    if (sqlite3_step(stmt) == SQLITE_ROW) {
        int count = sqlite3_column_int(stmt, 0);
        result = (count > 0);
    }

    sqlite3_finalize(stmt);
    return result;
}


