        "SELECT DISTINCT P.id_patient, P.nom, P.prenom "
        "FROM Consultation C "
        "JOIN Patient P ON P.id_patient = C.id_patient "
        "WHERE C.id_professionnel = ?;";

    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK)
        return;

    sqlite3_bind_text(stmt, 1, id_professionnel.c_str(), -1, SQLITE_TRANSIENT);

    std::cout << "ID Patient | Nom | Prenom\n";
    std::cout << "-------------------------------------\n";

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        std::cout << sqlite3_column_text(stmt, 0) << " | "
                  << sqlite3_column_text(stmt, 1) << " | "
                  << sqlite3_column_text(stmt, 2) << "\n";
    }

    sqlite3_finalize(stmt);
}


bool Database::mettre_a_jour_dossier(int id_dossier, double poids, double taille) {
