    if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) != SQLITE_OK) return false;

    sqlite3_bind_double(stmt, 1, poids);
    sqlite3_bind_double(stmt, 2, taille);
    sqlite3_bind_int(stmt, 3, id_dossier);

