vector<string> Database::patients_consultes(const string& id_professionnel)
{
    vector<string> liste;
    sqlite3_stmt* stmt;

    string sql =
        "SELECT DISTINCT Patient.id_patient "
        "FROM Consultation "
        "JOIN DossierMedical ON Consultation.id_dossier_medical = DossierMedical.id_dossier_medical "
        "JOIN Patient ON DossierMedical.id_patient = Patient.id_patient "
        "WHERE Consultation.id_professionnel = ?;";

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK)
        return liste;

    sqlite3_bind_text(stmt, 1, id_professionnel.c_str(), -1, SQLITE_TRANSIENT);

    while (sqlite3_step(stmt) == SQLITE_ROW) {
        liste.push_back(reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0)));
    }

    sqlite3_finalize(stmt);
    return liste;
}

