void DossierMedical::modifierDossierMedical() {
    string nom, prenom;
    cout << "Nom du patient : "; getline(cin, nom);
    cout << "Prenom du patient : "; getline(cin, prenom);

    Database db;
    string id_patient = db.get_id_patient(nom, prenom);
    if (id_patient.empty()) {
        cout << "Patient introuvable." << endl;
        return;
    }

    string newPoidsStr, newTailleStr;
    double newPoids = 0.0, newTaille = 0.0;

    cout << "Nouveau poids : "; getline(cin, newPoidsStr);
    cout << "Nouvelle taille : "; getline(cin, newTailleStr);

