// Inscrire un patient et créer automatiquement son dossier médical
string Patient::inscrirePatient() {
    string nom, prenom, sexe, dateNaissance, telephone, confirmation;
    double poids = 0.0, taille = 0.0;

    cout << "\n===== FORMULAIRE D'INSCRIPTION DU PATIENT =====\n";
    cout << "Nom : "; getline(cin, nom);
    cout << "Prenom : "; getline(cin, prenom);

    do {
        cout << "Sexe (M/F) : "; getline(cin, sexe);
        if (sexe != "M" && sexe != "F") cout << "Erreur : M ou F uniquement.\n";
    } while (sexe != "M" && sexe != "F");

    cout << "Date de naissance (YYYY-MM-DD) : "; getline(cin, dateNaissance);
    cout << "Telephone : "; getline(cin, telephone);

    while (true) {
        cout << "Poids (kg) : ";
        if (cin >> poids && poids > 0) break;
        cout << "Poids invalide.\n";
        cin.clear(); cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }

    while (true) {
        cout << "Taille (m) : ";
        if (cin >> taille && taille > 0) break;
        cout << "Taille invalide.\n";
        cin.clear(); cin.ignore(numeric_limits<streamsize>::max(), '\n');
    }
    cin.ignore(numeric_limits<streamsize>::max(), '\n'); // nettoyer le buffer

    cout << "Confirmer l'inscription ? [y/n] : "; getline(cin, confirmation);
    if (confirmation != "y") {
        cout << "Inscription annulee.\n";
        return "";
    }

    // Générer ID patient
    sqlite3* db;
    int count = 0;
    if (sqlite3_open("MediPass_DB.db", &db) == SQLITE_OK) {
        const char* sql_count = "SELECT COUNT(*) FROM Patient;";
        sqlite3_stmt* stmt;
        if (sqlite3_prepare_v2(db, sql_count, -1, &stmt, nullptr) == SQLITE_OK) {
            if (sqlite3_step(stmt) == SQLITE_ROW) count = sqlite3_column_int(stmt, 0);
            sqlite3_finalize(stmt);
        }
    } else {
        cerr << "Erreur ouverture BD\n";
        return "";
    }

    std::string id_patient = Patient::generer_id_patient();
    if (id_patient.empty()) {
        std::cerr << "Impossible de generer l'ID patient." << std::endl;
        return "";
    }

    // Insertion Patient
    const char* sql_insert_patient =
        "INSERT INTO Patient (id_patient, nom, prenom, date_naissance, sexe, telephone) VALUES (?, ?, ?, ?, ?, ?);";

    sqlite3_stmt* stmt;
    if (sqlite3_prepare_v2(db, sql_insert_patient, -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, id_patient.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 2, nom.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 3, prenom.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 4, dateNaissance.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 5, sexe.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 6, telephone.c_str(), -1, SQLITE_STATIC);
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            cerr << "Erreur ajout patient.\n";
            sqlite3_finalize(stmt);
            sqlite3_close(db);
            return "";
        }
        sqlite3_finalize(stmt);
    }

    // Création automatique du dossier médical
    const char* sql_insert_dm =
        "INSERT INTO DossierMedical (id_patient, poids, taille) VALUES (?, ?, ?);";

    if (sqlite3_prepare_v2(db, sql_insert_dm, -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, id_patient.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_double(stmt, 2, poids);
        sqlite3_bind_double(stmt, 3, taille);
        if (sqlite3_step(stmt) != SQLITE_DONE) {
            cerr << "Erreur ajout dossier medical.\n";
            sqlite3_finalize(stmt);
            sqlite3_close(db);
            return "";
        }
        sqlite3_finalize(stmt);
    }

    sqlite3_close(db);

    cout << "\nPatient enregistre avec succes. ID : " << id_patient << "\n";
    cout << "Nom      : " << nom << "\nPrenom   : " << prenom
         << "\nDate Naissance : " << dateNaissance
         << "\nSexe     : " << sexe
         << "\nTelephone: " << telephone
         << "\nPoids    : " << poids
         << "\nTaille   : " << taille << "\n\n";

    return id_patient;
}

