// Modifier les infos d'un patient
void Patient::modifierInfosPatients() {
    string id_patient, newNom, newPrenom, newDateNaissance, newTelephone, newSexe, confirm;

    cout << "ID du patient a modifier : "; getline(cin, id_patient);
    cout << "Nouveau nom : "; getline(cin, newNom);
    cout << "Nouveau prenom : "; getline(cin, newPrenom);
    cout << "Nouvelle date de naissance : "; getline(cin, newDateNaissance);
    cout << "Nouveau telephone : "; getline(cin, newTelephone);
    cout << "Sexe (M/F) : "; getline(cin, newSexe);

    cout << "Confirmer ? [y/n] : "; getline(cin, confirm);
    if (confirm != "y") return;

    string sql = "UPDATE Patient SET nom = '" + newNom + "', prenom = '" + newPrenom +
                 "', date_naissance = '" + newDateNaissance + "', telephone = '" + newTelephone +
                 "', sexe = '" + newSexe + "' WHERE id_patient = '" + id_patient + "';";

    sqlite3* db;
    char* errMsg = nullptr;
    if (sqlite3_open("MediPass_DB.db", &db) == SQLITE_OK) {
        if (sqlite3_exec(db, sql.c_str(), nullptr, nullptr, &errMsg) != SQLITE_OK) {
            cerr << "Erreur SQL : " << (errMsg ? errMsg : "unknown") << "\n";
            if (errMsg) sqlite3_free(errMsg);
        } else {
            cout << "Patient modifie avec succes.\n";
        }
        sqlite3_close(db);
    }
}


std::string Patient::generer_id_patient() {
    sqlite3* db;
    int count = 0;

    if (sqlite3_open("MediPass_DB.db", &db) != SQLITE_OK) {
        std::cerr << "Erreur ouverture base de donnees: " << sqlite3_errmsg(db) << std::endl;
        return "";
    }

    const char* sql_count = "SELECT COUNT(*) FROM Patient;";
    sqlite3_stmt* stmt;

    if (sqlite3_prepare_v2(db, sql_count, -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW) {
            count = sqlite3_column_int(stmt, 0);
        }
        sqlite3_finalize(stmt);
    } else {
        std::cerr << "Erreur SQL: " << sqlite3_errmsg(db) << std::endl;
        sqlite3_close(db);
        return "";
    }

    sqlite3_close(db);

    std::ostringstream oss;
    oss << "PA" << std::setw(4) << std::setfill('0') << (count + 1);
    return oss.str();
}

