// ================================================
// Verification du format de date YYYY-MM-DD
// ================================================
bool Statistiques::is_valid_date(const string& s) {
    if (s.size() != 10) return false;
    for (size_t i = 0; i < s.size(); ++i) {
        if (i == 4 || i == 7) { if (s[i] != '-') return false; }
        else if (s[i] < '0' || s[i] > '9') return false;
    }
    return true;
}

// ================================================
// Nombre de patients (total et par sexe)
// ================================================
void Statistiques::afficher_nombre_patients() {
    sqlite3* db = nullptr;
    sqlite3_stmt* stmt = nullptr;

    if (sqlite3_open("MediPass_DB.db", &db) != SQLITE_OK) {
        cerr << "Erreur ouverture BD: " << sqlite3_errmsg(db) << endl;
        return;
    }

    const char* sql =
        "SELECT COUNT(*) AS total, "
        "SUM(CASE WHEN sexe='M' THEN 1 ELSE 0 END) AS nb_m, "
        "SUM(CASE WHEN sexe='F' THEN 1 ELSE 0 END) AS nb_f "
        "FROM Patient;";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, nullptr) == SQLITE_OK) {
        if (sqlite3_step(stmt) == SQLITE_ROW) {
            int total = sqlite3_column_int(stmt, 0);
            int nb_m = sqlite3_column_int(stmt, 1);
            int nb_f = sqlite3_column_int(stmt, 2);

            cout << "\n\n==================== STATISTIQUES PATIENTS ====================\n\n";
            cout << "Nombre total de patients : " << total << "\n\n";
            cout << "Nombre de patients (M)  : " << nb_m << "\n\n";
            cout << "Nombre de patients (F)  : " << nb_f << "\n\n";
            cout << "===============================================================\n\n";
        }
        sqlite3_finalize(stmt);
    }

    sqlite3_close(db);
}

// ================================================
// Nombre de professionnels par specialite
// ================================================
void Statistiques::afficher_nombre_professionnels_par_specialite() {
    sqlite3* db = nullptr;
    sqlite3_stmt* stmt = nullptr;

    if (sqlite3_open("MediPass_DB.db", &db) != SQLITE_OK) {
        cerr << "Erreur ouverture BD: " << sqlite3_errmsg(db) << endl;
        return;
    }

    const string sql =
        "SELECT specialite, COUNT(*) "
        "FROM ProfessionnelDeSante "
        "GROUP BY specialite "
        "ORDER BY specialite ASC;";

    if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        cout << "\n\n================ PROFESSIONNELS PAR SPECIALITE ================\n\n";

        while (sqlite3_step(stmt) == SQLITE_ROW) {
            const char* sp = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
            int count = sqlite3_column_int(stmt, 1);
            cout << "Specialite : " << (sp ? sp : "(inconnu)") << "\n\n";
            cout << "Nombre     : " << count << "\n\n";
            cout << "---------------------------------------------------------------\n\n";
        }

        sqlite3_finalize(stmt);
    }

    sqlite3_close(db);
}

// ================================================
// Consultations par periode
// ================================================
void Statistiques::afficher_consultations_par_periode(const string& date_debut,
                                                      const string& date_fin) {
    string debut = date_debut;
    string fin = date_fin;

    if (debut.empty() || fin.empty()) {
        cout << "\nDate debut (YYYY-MM-DD) : ";
        getline(cin, debut);
        cout << "Date fin   (YYYY-MM-DD) : ";
        getline(cin, fin);
    }

    if (!is_valid_date(debut) || !is_valid_date(fin)) {
        cout << "\nFormat invalide. Utilisez YYYY-MM-DD.\n";
        return;
    }

    if (debut > fin) {
        cout << "\nErreur : date_debut > date_fin.\n";
        return;
    }

    sqlite3* db = nullptr;
    sqlite3_stmt* stmt = nullptr;

    if (sqlite3_open("MediPass_DB.db", &db) != SQLITE_OK) {
        cerr << "Erreur ouverture BD: " << sqlite3_errmsg(db) << endl;
        return;
    }

    // -------- Total consultations --------
    int total = 0;
    const string sql_total =
        "SELECT COUNT(*) FROM Consultation "
        "WHERE date_debut >= ? AND date_debut <= ?;";

    if (sqlite3_prepare_v2(db, sql_total.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, debut.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 2, fin.c_str(), -1, SQLITE_STATIC);

        if (sqlite3_step(stmt) == SQLITE_ROW) {
            total = sqlite3_column_int(stmt, 0);
        }
        sqlite3_finalize(stmt);
    }

    cout << "\n\n================= CONSULTATIONS DU " << debut << " AU " << fin << " =================\n\n";
    cout << "Total consultations : " << total << "\n\n";

    // -------- Details --------
    const string sql_details =
        "SELECT c.id_consultation, p.id_patient, c.id_professionnel, "
        "c.date_debut, c.date_fin, c.motif, c.diagnostic "
        "FROM Consultation c "
        "JOIN DossierMedical d ON c.id_dossier_medical = d.id_dossier_medical "
        "JOIN Patient p ON d.id_patient = p.id_patient "
        "WHERE c.date_debut >= ? AND c.date_debut <= ? "
        "ORDER BY c.date_debut ASC;";

    if (sqlite3_prepare_v2(db, sql_details.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
        sqlite3_bind_text(stmt, 1, debut.c_str(), -1, SQLITE_STATIC);
        sqlite3_bind_text(stmt, 2, fin.c_str(), -1, SQLITE_STATIC);

        cout << "\n---------------------- DETAILS DES CONSULTATIONS ----------------------\n\n";

        while (sqlite3_step(stmt) == SQLITE_ROW) {
            cout << "ID consultation   : " << sqlite3_column_int(stmt, 0) << "\n\n";
            cout << "ID patient        : " << sqlite3_column_text(stmt, 1) << "\n\n";
            cout << "ID professionnel : " << sqlite3_column_text(stmt, 2) << "\n\n";
            cout << "Debut             : " << sqlite3_column_text(stmt, 3) << "\n\n";
            cout << "Fin               : " << sqlite3_column_text(stmt, 4) << "\n\n";
            cout << "Motif             : " << sqlite3_column_text(stmt, 5) << "\n\n";
           // cout << "Diagnostic        : " << sqlite3_column_text(stmt, 6) << "\n\n";
            cout << "=======================================================================\n\n";
            cout << "-----------------------------------------------------------------------\n\n";
        }

        sqlite3_finalize(stmt);
    }

    cout << "=======================================================================\n\n";

    sqlite3_close(db);
}
